package com.evidencevault.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="users")
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=100) private String username; @Column(nullable=false,unique=true,length=150) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="role_id") private Role role; private boolean enabled=true; @Column(nullable=false) private int failedLoginAttempts=0; private LocalDateTime lockedUntil; @Column(nullable=false) private LocalDateTime createdAt; private LocalDateTime updatedAt;
 @PrePersist void pre(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void upd(){updatedAt=LocalDateTime.now();}
 public Long getId(){return id;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public int getFailedLoginAttempts(){return failedLoginAttempts;} public void setFailedLoginAttempts(int v){failedLoginAttempts=v;} public LocalDateTime getLockedUntil(){return lockedUntil;} public void setLockedUntil(LocalDateTime v){lockedUntil=v;} public boolean isLocked(){return lockedUntil!=null && lockedUntil.isAfter(LocalDateTime.now());} public LocalDateTime getCreatedAt(){return createdAt;} }
